#[test]
fn renders_app_game_exclusive_in_every_language() {
    let args: &[(&str, ArgValue)] = &[("game", ArgValue::Text("<GAME>".to_owned()))];
    assert_eq!(render(Lang::En, "app.game_exclusive", args), "<GAME> used exclusive full screen, where no window can be shown on top, not even with maximum overlay. In its video settings, choose borderless or windowed full screen.");
    assert_eq!(render(Lang::Es, "app.game_exclusive", args), "<GAME> usó pantalla completa exclusiva, donde ninguna ventana puede mostrarse encima, ni siquiera con la superposición máxima. En su configuración de video, elige pantalla completa sin bordes o en ventana.");
    assert_eq!(render(Lang::Ru, "app.game_exclusive", args), "<GAME> использовала эксклюзивный полноэкранный режим: поверх него нельзя показать никакое окно, даже с максимальным наложением. В настройках графики игры выберите полноэкранный режим без рамки или оконный.");
    assert_eq!(render(Lang::Pl, "app.game_exclusive", args), "<GAME> korzystała z wyłącznego trybu pełnoekranowego, nad którym nie da się pokazać żadnego okna, nawet z maksymalną nakładką. W ustawieniach grafiki gry wybierz pełny ekran bez ramek albo tryb okienkowy.");
    assert_eq!(render(Lang::Ja, "app.game_exclusive", args), "<GAME> は排他的フルスクリーンを使っていたため、上にウィンドウを表示できませんでした（最大オーバーレイでも同じです）。ゲームのグラフィック設定で、ボーダーレス フルスクリーンかウィンドウ表示を選んでください。");
}

