#[test]
fn renders_app_page_changed_in_every_language() {
    let args: &[(&str, ArgValue)] = &[("service", ArgValue::Text("<SERVICE>".to_owned()))];
    assert_eq!(render(Lang::En, "app.page_changed", args), "<SERVICE> changed its page, so some of the app's controls (video only, full screen, the music bar) may not work until the next update. The session diary lists what's missing.");
    assert_eq!(render(Lang::Es, "app.page_changed", args), "<SERVICE> cambió su página, así que algunos controles de la app (solo video, pantalla completa, la barra de música) podrían fallar hasta la próxima actualización. El diario de sesión dice qué falta.");
    assert_eq!(render(Lang::Ru, "app.page_changed", args), "<SERVICE> изменил свою страницу, поэтому некоторые элементы управления приложения (только видео, полноэкранный режим, музыкальная панель) могут не работать до следующего обновления. Чего не хватает, записано в журнале сеанса.");
    assert_eq!(render(Lang::Pl, "app.page_changed", args), "<SERVICE> zmienił swoją stronę, więc niektóre funkcje aplikacji (tylko wideo, pełny ekran, pasek muzyki) mogą nie działać do następnej aktualizacji. W dzienniku sesji jest lista tego, czego brakuje.");
    assert_eq!(render(Lang::Ja, "app.page_changed", args), "<SERVICE> のページが変更されたため、次の更新まで一部の操作（動画のみ、全画面、ミュージック バー）が動かない可能性があります。足りない部分はセッションの記録に残っています。");
}

